/* Final interface polish. Data, numbering and financial approval rules remain in their existing modules. */
const statusBeforeProfessionalPolish=jobStatusLabel;
jobStatusLabel=function(j){if(j.status==='Scheduled')return 'Appointment booked';if(j.status==='In progress')return 'Work underway';if(j.status==='Completed')return 'Work completed';if(j.status==='Awaiting schedule')return 'Ready to schedule';if(j.status==='Awaiting approval')return 'Awaiting property manager approval';return statusBeforeProfessionalPolish(j)};
const filterLabelBeforeProfessionalPolish=statusFilterLabel;
statusFilterLabel=function(s){return {'Scheduled':'Appointment booked','In progress':'Work underway','Completed':'Work completed','Awaiting schedule':'Ready to schedule','Awaiting approval':'Awaiting property manager approval'}[s]||filterLabelBeforeProfessionalPolish(s)};
stages.find(s=>s[0]==='approval')[1]='Awaiting property manager approval';
// The legacy landing renderer must use the current searchable, 19-category guide.
renderGuidedLanding=function(){renderReport()};
function professionalNextStep(j){if(role==='sevlink')return nextAction(j)||'Review the job record.';if(j.status==='Cancelled')return 'This job is cancelled. Its records remain available.';if(j.sentToSevlink===false)return role==='tenant'?'Your property manager is reviewing your report.':'Review the tenant report and send the authorised request to Sevlink.';if(j.status==='Awaiting approval')return role==='tenant'?'Your property manager is reviewing the proposed work.':'Review the quote and approve it, request a revision or reject it.';if(j.status==='Scheduled')return j.access?.status==='Confirmed'?'Access is confirmed for your Sevlink appointment.':role==='tenant'?'Confirm access for your Sevlink appointment.':'Sevlink is arranging the appointment and tenant access.';if(j.status==='In progress')return 'Sevlink is on site. Follow progress in the job timeline.';if(j.status==='Completed')return role==='tenant'?'The work is complete. Your Sevlink report is available.':'Review the work report and any remaining invoice balance.';return role==='tenant'?'Sevlink will update this repair once the next step is confirmed.':'Sevlink will update the job as quoting, access and attendance progress.'}
const detailBeforeProfessionalPolish=jobDetail;
jobDetail=function(jid,section='comments'){detailBeforeProfessionalPolish(jid,section);const j=getJob(jid);if(!j)return;const tabs=modal.querySelector('.tabs');if(tabs)tabs.insertAdjacentHTML('beforebegin',`<div class="professional-next-step"><span class="eyebrow">NEXT STEP</span><p>${esc(professionalNextStep(j))}</p></div>`)};
let professionalFieldId=0;
function showProfessionalFormError(form,message,input){if(!form?.isConnected)return;const box=form.querySelector('[data-form-feedback]');if(box){box.hidden=false;box.textContent=message;box.scrollIntoView?.({block:'nearest',behavior:'smooth'})}if(input)input.setAttribute('aria-invalid','true')}
function submissionGuard(form,submit){let saving=false;return async function(event){event.preventDefault();if(saving)return;saving=true;form.dataset.saving='true';form.setAttribute('aria-busy','true');const button=form.querySelector('button[type="submit"]'),text=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…'}try{return await submit(event)}finally{saving=false;if(form.isConnected){form.dataset.saving='false';form.removeAttribute('aria-busy');if(button){button.disabled=false;button.textContent=text}}}}}
const openFormBeforeProfessionalPolish=openForm;
openForm=function(title,content,submit,handler){openFormBeforeProfessionalPolish(title,content,submit,handler);const form=modal.querySelector('#form');if(!form)return;let dirty=false;const feedback=form.querySelector('#paymentSaveError')||document.createElement('div');feedback.dataset.formFeedback='true';feedback.classList.add('professional-form-feedback');feedback.setAttribute('role','alert');feedback.setAttribute('aria-live','polite');if(!feedback.parentNode){feedback.hidden=true;form.prepend(feedback)}
form.querySelectorAll('input,select,textarea').forEach(input=>{if(input.type==='hidden')return;let label=input.labels?.[0];if(!label&&input.previousElementSibling?.tagName==='LABEL'){label=input.previousElementSibling;input.id||='professional-field-'+(++professionalFieldId);label.htmlFor=input.id}if(label&&input.required&&!label.querySelector('.required-marker')){const mark=document.createElement('span');mark.className='required-marker';mark.textContent=' *';mark.setAttribute('aria-hidden','true');label.append(mark)}});
form.addEventListener('invalid',event=>{const field=event.target,label=(field.labels?.[0]?.textContent||field.name||'required field').replace(/\*/g,'').trim();showProfessionalFormError(form,label+': '+(field.validationMessage||'Please complete this field.'),field)},true);
form.addEventListener('input',event=>{dirty=true;event.target.removeAttribute?.('aria-invalid');feedback.hidden=true;feedback.textContent=''});form.addEventListener('change',()=>dirty=true);const submitHandler=form.onsubmit;form.onsubmit=submissionGuard(form,async event=>{feedback.hidden=true;feedback.textContent='';await submitHandler(event);if(form.isConnected&&!feedback.textContent)showProfessionalFormError(form,'The change has not been saved. Check the details and try again. Your entries are still here.')});
const close=modal.querySelector('.close');if(close)close.onclick=()=>{if(form.dataset.saving==='true'){showProfessionalFormError(form,'Please wait for saving to finish.');return}if(!dirty||confirm('Discard the unsaved changes?'))modal.close()};modal.oncancel=event=>{if(!form.isConnected)return;if(form.dataset.saving==='true'){event.preventDefault();return}if(dirty&&!confirm('Discard the unsaved changes?'))event.preventDefault()};const back=modal.querySelector('#formBack'),beforeBack=back?.onclick;if(back)back.onclick=event=>{if(form.dataset.saving==='true'){showProfessionalFormError(form,'Please wait for saving to finish.');return}beforeBack?.(event)};
};
const toastBeforeProfessionalPolish=toast;
toast=function(message){const form=modal.querySelector('#form');if(form?.dataset.saving==='true')showProfessionalFormError(form,message);toastBeforeProfessionalPolish(message)};

const sevlinkLegalName='Influx Solar Energy (Pty) Ltd t/a Sevlink';
function sevlinkDocumentHeader(title,reference,logo='sevlink-logo.png'){return `<div class="document-header">${logo?`<img src="${logo}" alt="Sevlink Property Maintenance">`:'<strong class="document-wordmark">SEVLINK</strong>'}<div><span class="eyebrow">SEVLINK PROPERTY MAINTENANCE</span><h1>${esc(title)}</h1><p>${esc(reference)}</p></div></div><div class="document-company"><b>${sevlinkLegalName}</b><br>081 028 5034 · info@sevlink.co.za · www.sevlink.co.za</div>`}
function sevlinkDocumentProperty(j){const p=property(j.property),a=state.agencies.find(a=>a.id===j.agency),pm=state.members?.find(m=>m.id===p?.manager);return `<div class="document-property"><h2>${esc(p?.address||p?.name)}</h2><p>${esc(p?.name)}<br><b>${esc(j.title)}</b><br>Job reference: ${esc(j.ref)} · ${esc(j.category)}<br>Agency: ${esc(a?.name)}${pm?'<br>Property manager: '+esc(pm.name):''}</p></div>`}
function professionalQuoteMarkup(j,q,logo){return `<article class="sevlink-document">${sevlinkDocumentHeader('Quote summary',q.number||q.quoteNumber||j.ref,logo)}${sevlinkDocumentProperty(j)}<div class="document-totals"><span>Quote total</span><strong>${money(q.amount)}</strong><span>Decision</span><b>${esc(q.status)}</b></div><h3>Proposed work</h3><p>${esc(q.scope)}</p><p>Uploaded: ${date(q.at)}<br>Original quote document: ${esc(q.file?.name||'Not attached')}</p><p class="document-note">This summary accompanies the uploaded quote document. Review that document for its full scope and terms.</p></article>`}
const quotesBeforeProfessionalPolish=renderQuotes;
renderQuotes=function(j){quotesBeforeProfessionalPolish(j);if(role==='tenant')return;for(const q of j.quotes)$('#jobcontent').insertAdjacentHTML('beforeend',`<div class="actions"><button class="secondary" onclick="quoteSummary('${j.id}','${q.id}')">Review quote summary · ${money(q.amount)}</button></div>`)};
function quoteSummary(jid,qid){const j=getJob(jid),q=j?.quotes.find(q=>q.id===qid);if(!q||role==='tenant')return;enterDialogRoute({type:'quoteSummary',jid,qid});modal.innerHTML=`<button class="close" onclick="modal.close()" aria-label="Close">×</button>${professionalQuoteMarkup(j,q)}<div class="actions">${q.file?`<button class="primary" id="originalQuoteDocument">Download original quote</button>`:''}<button class="secondary" onclick="downloadQuoteSummary('${jid}','${qid}')">Download summary</button></div>`;if(!modal.open)modal.showModal();if($('#originalQuoteDocument'))$('#originalQuoteDocument').onclick=()=>download(q.file);decorateDialogBack()}
const showRouteBeforeProfessionalPolish=showDialogRoute;
showDialogRoute=function(route){if(route?.type!=='quoteSummary')return showRouteBeforeProfessionalPolish(route);if(dialogUserScope()!==dialogRouteScope){modal.close();return}replayingDialog=true;try{quoteSummary(route.jid,route.qid)}finally{replayingDialog=false}};
const routeLabelBeforeProfessionalPolish=dialogRouteLabel;dialogRouteLabel=function(route){return route?.type==='quoteSummary'?'quote summary':routeLabelBeforeProfessionalPolish(route)};

reportMarkup=function(j,logo){return `<article class="completion-report sevlink-document">${sevlinkDocumentHeader('Work completion report',j.ref,logo)}${sevlinkDocumentProperty(j)}<div class="document-note">${j.completedAt?'Completed: '+date(j.completedAt):'Draft · completion has not been recorded'}</div><h3>Work carried out</h3><p>${esc(j.completionNotes||'No completion summary recorded yet.')}</p><div class="photo-pair">${[['Before',j.beforePhotos||[]],['After',j.afterPhotos||[]]].map(([label,photos])=>`<div><h3>${label}</h3>${photos.length?photos.map(p=>`<img src="${p.data}" alt="${label} repair photo">`).join(''):'<div class="photo-placeholder">No '+label.toLowerCase()+' photo recorded</div>'}</div>`).join('')}</div><h3>Checks & recommendations</h3><p>${esc(j.completionChecks||'No additional recommendations recorded.')}</p><footer class="document-footer">Prepared by Sevlink · Your Property. Our Priority.</footer></article>`};
function professionalInvoiceEmailMarkup(j,i,logo){const remaining=invoiceBalance(i),requested=Math.min(remaining,i.requestedAmount??remaining);return `<article class="sevlink-document">${sevlinkDocumentHeader('Invoice payment request',i.number,logo)}${sevlinkDocumentProperty(j)}<p>Hi ${esc(i.billTo||'Property manager')},</p><p>Please find the company invoice attached for the work shown above.</p><div class="document-totals"><span>Invoice total</span><strong>${money(i.amount)}</strong><span>Verified payments received</span><b>${money(invoicePaid(i))}</b><span>Remaining balance</span><strong>${money(remaining)}</strong><span>Amount requested now</span><strong>${money(requested)}</strong></div><p>Invoice date: ${esc(i.issueDate||'Not recorded')}<br>Due date: ${esc(i.dueDate||'Not recorded')}<br>Invoice status: ${esc(invoiceState(i))}</p><p>Please use the invoice number as your payment reference. Refer to the attached original invoice for payment terms and banking details.</p><p>Kind regards,<br>Sevlink Property Maintenance</p></article>`}
invoicePreview=function(jid,iid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid);if(!i||role==='tenant')return;enterDialogRoute({type:'invoicePreview',jid,iid});modal.innerHTML=`<button class="close" onclick="modal.close()" aria-label="Close">×</button><div class="notice"><b>Email preview · not sent</b><br>To: ${esc(i.email)}<br>Subject: Sevlink invoice ${esc(i.number)} · ${esc(property(j.property)?.address||property(j.property)?.name)}</div>${professionalInvoiceEmailMarkup(j,i)}<div class="actions"><button class="primary" id="originalInvoiceDocument">Download original invoice</button><button class="secondary" onclick="downloadInvoiceEmail('${jid}','${iid}')">Download payment request</button></div><p class="muted">No email or payment link is sent by this demo.</p>`;if(!modal.open)modal.showModal();$('#originalInvoiceDocument').onclick=()=>download(i.file);decorateDialogBack()};
let professionalLogoPromise;
async function professionalLogo(){professionalLogoPromise??=fetch('sevlink-logo.png').then(r=>{if(!r.ok)throw Error('Logo unavailable');return r.blob()}).then(blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})).catch(()=>null);return professionalLogoPromise}
function professionalDocumentHtml(title,content){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${professionalDocumentStyles}</style></head><body>${content}<p class="print-help">Print this document and choose Save as PDF if required.</p></body></html>`}
function professionalDownload(title,content,filename){fileDownload(new Blob([professionalDocumentHtml(title,content)],{type:'text/html'}),filename.replace(/[^a-z0-9_.-]/gi,'_')+'.html')}
async function downloadReport(jid){const j=getJob(jid);if(!j)return;const logo=await professionalLogo();professionalDownload('Work completion report · '+j.ref,reportMarkup(j,logo||''),j.ref+'-completion-report')}
async function downloadQuoteSummary(jid,qid){const j=getJob(jid),q=j?.quotes.find(q=>q.id===qid);if(!q||role==='tenant')return;const logo=await professionalLogo();professionalDownload('Quote summary · '+j.ref,professionalQuoteMarkup(j,q,logo||''),j.ref+'-quote-summary')}
async function downloadInvoiceEmail(jid,iid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid);if(!i||role==='tenant')return;const logo=await professionalLogo();professionalDownload('Invoice payment request · '+i.number,professionalInvoiceEmailMarkup(j,i,logo||''),i.number+'-payment-request')}
async function downloadPaymentReceipt(jid,iid,pid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid),p=i?.payments.find(p=>p.id===pid);if(role==='tenant'||p?.verification!=='Verified')return;const logo=await professionalLogo();const html=`<article class="sevlink-document">${sevlinkDocumentHeader('Payment acknowledgement',i.number,logo||'')}${sevlinkDocumentProperty(j)}<div class="document-totals"><span>Payment received</span><strong>${money(p.amount)}</strong><span>Invoice total</span><b>${money(i.amount)}</b><span>Total verified payments</span><b>${money(invoicePaid(i))}</b><span>Outstanding balance</span><strong>${money(invoiceBalance(i))}</strong></div><p>Payment date: ${esc(p.date)}<br>Reference: ${esc(p.reference)}<br>Payment type: ${esc(p.purpose||'Payment')}<br>Verified: ${date(p.verifiedAt||p.at)}</p><p class="document-note">This acknowledges a verified payment against the original company invoice. It does not replace or renumber that invoice.</p></article>`;professionalDownload('Payment acknowledgement · '+i.number,html,i.number+'-'+p.id+'-payment-receipt')}
const professionalDocumentStyles=`*{box-sizing:border-box}body{max-width:850px;margin:36px auto;padding:24px;font:14px Arial,sans-serif;color:#12345a;background:white}p{line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}h1{font-size:26px;margin:8px 0}h2{font-size:20px}h3{font-size:15px;margin-top:25px}.document-header{display:flex;gap:22px;align-items:center;padding-bottom:20px;border-bottom:3px solid #006bb0}.document-header img{width:140px;height:95px;object-fit:contain}.document-company{padding:15px 0;font-size:12px;line-height:1.7;color:#50657c}.eyebrow{font-size:10px;letter-spacing:1.5px;font-weight:bold;color:#006bb0}.document-property{padding:18px;background:#f2f7fb;border-left:3px solid #006bb0;margin:12px 0 22px}.document-property h2{margin:0 0 8px}.document-property p{margin:0}.document-totals{display:grid;grid-template-columns:1fr auto;gap:12px;padding:20px;background:#f2f7fb;border:1px solid #dce5ee;border-radius:8px;margin:20px 0}.document-note{font-size:12px;color:#50657c;border-top:1px solid #dce5ee;padding-top:15px;line-height:1.7}.document-footer{margin-top:30px;border-top:1px solid #dce5ee;padding-top:15px;font-size:12px}.photo-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.photo-pair img{width:100%;max-height:350px;object-fit:contain;border:1px solid #dce5ee;border-radius:6px;margin:8px 0}.photo-placeholder{background:#f2f7fb;padding:35px 12px;color:#64748b}.print-help{font-size:12px;color:#64748b}@media(max-width:600px){body{padding:16px;margin:10px auto}.document-header{gap:12px}.document-header img{width:95px;height:75px}h1{font-size:22px}.photo-pair{grid-template-columns:1fr}}@media print{body{margin:0;max-width:none;padding:12mm}.document-header,.document-property,.document-totals,.photo-pair>div{break-inside:avoid}.print-help{display:none}h2,h3{break-after:avoid}}`;
